```javascript
// Callbacks
function fetchUserCallback(id, callback) {
  setTimeout(() => {
    if (id > 0) {
      callback(null, { id, name: 'John' });
    } else {
      callback(new Error('Invalid ID'), null);
    }
  }, 1000);
}

// Promises
function fetchUserPromise(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id > 0) {
        resolve({ id, name: 'John' });
      } else {
        reject(new Error('Invalid ID'));
      }
    }, 1000);
  });
}

// Async/Await
async function fetchUser(id) {
  try {
    const response = await fetch(`/api/users/${id}`);
    const user = await response.json();
    return user;
  } catch (error) {
    console.error('Error:', error);
    throw error;
  }
}

// Usage comparison
// Callback hell
fetchUserCallback(1, (err, user) => {
  if (!err) {
    fetchUserCallback(user.managerId, (err, manager) => {
      // nested callbacks...
    });
  }
});

// Promise chaining
fetchUserPromise(1)
  .then(user => fetchUserPromise(user.managerId))
  .then(manager => console.log(manager))
  .catch(error => console.error(error));

// Async/await (cleanest)
try {
  const user = await fetchUser(1);
  const manager = await fetchUser(user.managerId);
  console.log(manager);
} catch (error) {
  console.error(error);
}
```

questions.backOfCard:
**Explanation:**
• Callbacks: oldest method, prone to callback hell
• Promises: better error handling and chaining
• Async/await: cleanest syntax, built on Promises

**Usage:**
```javascript
// Callback
fetchUser(1, (err, user) => { /* handle */ });

// Promise
fetchUser(1)
  .then(user => console.log(user))
  .catch(err => console.error(err));

// Async/await
try {
  const user = await fetchUser(1);
  console.log(user);
} catch (error) {
  console.error(error);
}
```

**Real World Example:**
E-commerce checkout: callbacks for legacy APIs, Promises for modern calls, async/await for main flow (validate → charge → update inventory).

questions.usage:
```javascript
// Function declarations are fully hoisted
console.log(sayHello()); // "Hello!" - works!

function sayHello() {
  return "Hello!";
}

// Function expressions are not fully hoisted
console.log(sayGoodbye()); // TypeError: sayGoodbye is not a function

var sayGoodbye = function() {
  return "Goodbye!";
};

// What JavaScript actually does (hoisting visualization):
var sayGoodbye; // Declaration hoisted, undefined

console.log(sayGoodbye()); // undefined(), causes error

sayGoodbye = function() { // Assignment stays in place
  return "Goodbye!";
};

// Let and const hoisting (temporal dead zone)
console.log(x); // ReferenceError: Cannot access 'x' before initialization
let x = 5;

// Arrow functions behave like function expressions
console.log(arrow()); // TypeError
const arrow = () => "Arrow function";

// Class hoisting
console.log(new MyClass()); // ReferenceError
class MyClass {}
```

questions.backOfCard:
**Explanation:**
• Hoisting moves declarations to top of scope during compilation
• Function declarations: fully hoisted (callable before declaration)
• Function expressions: only declaration hoisted, not initialization

**Usage:**
```javascript
// Works - function declaration fully hoisted
console.log(sayHello()); // "Hello!"
function sayHello() { return "Hello!"; }

// Error - function expression not fully hoisted
console.log(sayGoodbye()); // TypeError
var sayGoodbye = function() { return "Goodbye!"; };

// Let/const have temporal dead zone
console.log(x); // ReferenceError
let x = 5;
```

**Real World Example:**
Web app initialization: utility functions (formatDate) are callable anywhere due to hoisting, const config objects must be declared before use.

