```javascript
// Global context
console.log(this); // window (browser) or global (Node.js)

// Object method
const user = {
  name: 'John',
  greet() {
    console.log(`Hello, ${this.name}`);
  }
};
user.greet(); // "Hello, John" - this refers to user object

// Method extracted (loses context)
const greet = user.greet;
greet(); // "Hello, undefined" - this refers to global

// Arrow functions (lexical this)
const userArrow = {
  name: 'Jane',
  greet: () => {
    console.log(`Hello, ${this.name}`); // this from enclosing scope
  },
  greetNormal() {
    const inner = () => {
      console.log(`Hello, ${this.name}`); // this refers to userArrow
    };
    inner();
  }
};

// Constructor function
function Person(name) {
  this.name = name; // this refers to new instance
}
const john = new Person('John');

// Explicit binding
const user1 = { name: 'Alice' };
const user2 = { name: 'Bob' };

function introduce() {
  console.log(`Hi, I'm ${this.name}`);
}

introduce.call(user1); // "Hi, I'm Alice"
introduce.apply(user2); // "Hi, I'm Bob"
const boundIntroduce = introduce.bind(user1);
boundIntroduce(); // "Hi, I'm Alice"

// Event handlers
button.addEventListener('click', function() {
  console.log(this); // button element
});

button.addEventListener('click', () => {
  console.log(this); // outer scope (not button)
});
```

questions.backOfCard:
**Explanation:**
• 'this' refers to the object executing the current function
• Value depends on how function is called
• Global context, object method, constructor, or explicit binding

**Usage:**
```javascript
// Object method
const user = {
  name: 'John',
  greet() { console.log(this.name); } // 'John'
};

// Lost context
const greet = user.greet;
greet(); // undefined

// Explicit binding
greet.call(user); // 'John'
const bound = greet.bind(user);

// Arrow functions use lexical this
```

**Real World Example:**
React class components need binding for event handlers; jQuery uses 'this' for clicked DOM elements in event handlers.

