```javascript
// Callback hell example
getUser(userId, (user) => {
  getProfile(user.id, (profile) => {
    getPreferences(profile.id, (preferences) => {
      updateSettings(preferences, (result) => {
        console.log('Done:', result);
      });
    });
  });
});

// Solution 1: Named functions
function handleUser(user) {
  getProfile(user.id, handleProfile);
}

function handleProfile(profile) {
  getPreferences(profile.id, handlePreferences);
}

function handlePreferences(preferences) {
  updateSettings(preferences, (result) => {
    console.log('Done:', result);
  });
}

getUser(userId, handleUser);

// Solution 2: Promises with chaining
getUserPromise(userId)
  .then(user => getProfilePromise(user.id))
  .then(profile => getPreferencesPromise(profile.id))
  .then(preferences => updateSettingsPromise(preferences))
  .then(result => console.log('Done:', result))
  .catch(error => console.error('Error:', error));

// Solution 3: Async/await
async function handleUserFlow(userId) {
  try {
    const user = await getUser(userId);
    const profile = await getProfile(user.id);
    const preferences = await getPreferences(profile.id);
    const result = await updateSettings(preferences);
    console.log('Done:', result);
  } catch (error) {
    console.error('Error:', error);
  }
}

// Solution 4: Promise.all for parallel operations
async function loadDashboard(userId) {
  try {
    const [user, posts, notifications] = await Promise.all([
      getUser(userId),
      getUserPosts(userId),
      getNotifications(userId)
    ]);

    return { user, posts, notifications };
  } catch (error) {
    console.error('Failed to load dashboard:', error);
  }
}
```

questions.backOfCard:
**Explanation:**
• Callback hell: deeply nested callbacks creating hard-to-read code
• Solutions: Promises, async/await, named functions, control flow libraries
• Improves readability, error handling, and maintainability

**Usage:**
```javascript
// Callback hell
getUser(id, (user) => {
  getProfile(user.id, (profile) => {
    getPrefs(profile.id, (prefs) => { /* nested */ });
  });
});

// Async/await solution
try {
  const user = await getUser(id);
  const profile = await getProfile(user.id);
  const prefs = await getPrefs(profile.id);
} catch (error) { /* handle */ }
```

**Real World Example:**
E-commerce checkout: sequential async/await for validate → payment → inventory → email flow, Promise.all for parallel user data + tax calculation.

