```javascript
// Debouncing implementation
function debounce(func, delay) {
  let timeoutId;
  return function (...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => func.apply(this, args), delay);
  };
}

// Throttling implementation
function throttle(func, delay) {
  let lastCall = 0;
  return function (...args) {
    const now = Date.now();
    if (now - lastCall >= delay) {
      lastCall = now;
      func.apply(this, args);
    }
  };
}

// Alternative throttling with leading and trailing edge
function throttleAdvanced(func, delay, options = {}) {
  let timeoutId;
  let lastCall = 0;
  const { leading = true, trailing = true } = options;

  return function (...args) {
    const now = Date.now();

    if (!lastCall && !leading) {
      lastCall = now;
    }

    const remaining = delay - (now - lastCall);

    if (remaining <= 0 || remaining > delay) {
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
      lastCall = now;
      func.apply(this, args);
    } else if (!timeoutId && trailing) {
      timeoutId = setTimeout(() => {
        lastCall = leading ? 0 : Date.now();
        timeoutId = null;
        func.apply(this, args);
      }, remaining);
    }
  };
}

// Usage examples
// Debounced search
const debouncedSearch = debounce((query) => {
  console.log('Searching for:', query);
  // API call here
}, 300);

input.addEventListener('input', (e) => {
  debouncedSearch(e.target.value);
});

// Throttled scroll handler
const throttledScroll = throttle(() => {
  console.log('Scroll position:', window.scrollY);
  // Update navigation or lazy load images
}, 100);

window.addEventListener('scroll', throttledScroll);

// Throttled button click (prevent spam)
const throttledSave = throttle(() => {
  console.log('Saving data...');
  // API save call
}, 2000);

saveButton.addEventListener('click', throttledSave);
```

questions.backOfCard:
**Explanation:**
• Debouncing: delays execution until after specified time since last call
• Throttling: limits execution to once per time interval
• Debouncing for events after activity stops, throttling for limiting frequency

**Usage:**
```javascript
// Debounce
function debounce(func, delay) {
  let timeoutId;
  return (...args) => {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => func(...args), delay);
  };
}

// Throttle
function throttle(func, delay) {
  let lastCall = 0;
  return (...args) => {
    if (Date.now() - lastCall >= delay) {
      lastCall = Date.now();
      func(...args);
    }
  };
}
```

**Real World Example:**
E-commerce: debounce search input (300ms), throttle scroll for infinite loading (100ms), throttle Add to Cart (1s) to prevent duplicates.

