// WeakMap example
const wm = new WeakMap();
const obj1 = {};
const obj2 = {};

wm.set(obj1, 'value1');
wm.set(obj2, 'value2');

console.log(wm.get(obj1)); // 'value1'
console.log(wm.has(obj2)); // true

// When obj1 is no longer referenced elsewhere, it can be garbage collected
// and automatically removed from WeakMap

// WeakSet example
const ws = new WeakSet();
ws.add(obj1);
ws.add(obj2);

console.log(ws.has(obj1)); // true

// Practical use case: Private data storage
const privateData = new WeakMap();

class User {
  constructor(name, email) {
    this.name = name;
    // Store private data
    privateData.set(this, { email, createdAt: new Date() });
  }

  getEmail() {
    return privateData.get(this).email;
  }

  getCreatedAt() {
    return privateData.get(this).createdAt;
  }
}

const user = new User('John', 'john@example.com');
console.log(user.getEmail()); // 'john@example.com'
// user.email is not directly accessible

// DOM node metadata without memory leaks
const nodeMetadata = new WeakMap();

function attachMetadata(element, data) {
  nodeMetadata.set(element, data);
}

function getMetadata(element) {
  return nodeMetadata.get(element);
}

// When DOM elements are removed, metadata is automatically cleaned up
const button = document.createElement('button');
attachMetadata(button, { clickCount: 0, created: Date.now() });

// Tracking object instances without preventing GC
const trackedObjects = new WeakSet();

function trackObject(obj) {
  trackedObjects.add(obj);
  console.log('Object tracked');
}

function isTracked(obj) {
  return trackedObjects.has(obj);
}
```

questions.backOfCard:
**Explanation:**
• WeakMap/WeakSet hold weak references, allow garbage collection
• Not iterable, only accept objects as keys/values
• Prevent memory leaks in temporary associations

**Usage:**
```javascript
const privateData = new WeakMap();

class User {
  constructor(name, email) {
    this.name = name;
    privateData.set(this, { email }); // Private storage
  }
  getEmail() {
    return privateData.get(this).email;
  }
}

// DOM metadata without leaks
const nodeData = new WeakMap();
nodeData.set(element, { clicks: 0 });
// Cleans up when element removed
```

**Real World Example:**
Web apps: WeakMap for DOM element metadata that auto-cleans when elements removed; React component instance data preventing GC issues.

