```javascript
// Memory leak examples and solutions

// 1. Forgotten event listeners
function badEventHandler() {
  const button = document.getElementById('myButton');
  const data = new Array(1000000).fill('data'); // Large data

  button.addEventListener('click', function() {
    console.log(data.length); // Closure keeps data alive
  });
  // No cleanup - memory leak!
}

// Solution: Remove event listeners
function goodEventHandler() {
  const button = document.getElementById('myButton');
  const data = new Array(1000000).fill('data');

  function clickHandler() {
    console.log(data.length);
  }

  button.addEventListener('click', clickHandler);

  // Cleanup function
  return () => {
    button.removeEventListener('click', clickHandler);
  };
}

// 2. Forgotten timers
function createTimer() {
  const data = new Array(1000000).fill('data');

  setInterval(() => {
    console.log(data.length); // Keeps data alive forever
  }, 1000);
  // Timer never cleared - memory leak!
}

// Solution: Clear timers
function createTimerWithCleanup() {
  const data = new Array(1000000).fill('data');

  const intervalId = setInterval(() => {
    console.log(data.length);
  }, 1000);

  // Return cleanup function
  return () => clearInterval(intervalId);
}

// 3. Circular references (less common in modern JS)
function createCircularReference() {
  const obj1 = {};
  const obj2 = {};

  obj1.ref = obj2;
  obj2.ref = obj1; // Circular reference

  // In old browsers, this could cause leaks
  // Modern engines handle this with mark-and-sweep
}

// 4. Closures holding large objects
function createClosure() {
  const largeData = new Array(1000000).fill('data');

  return function(index) {
    return largeData[index]; // Entire array stays in memory
  };
}

// Solution: Extract only what you need
function createOptimizedClosure() {
  const largeData = new Array(1000000).fill('data');
  const neededData = largeData.slice(0, 100); // Take only what's needed

  return function(index) {
    return neededData[index]; // Only small array in memory
  };
}

// 5. DOM references
function createDOMReference() {
  const elements = [];

  // Bad: keeping references to removed DOM elements
  document.querySelectorAll('.item').forEach(el => {
    elements.push(el);
  });

  // Even if elements are removed from DOM, they stay in memory
  return elements;
}

// Memory monitoring
function monitorMemory() {
  if (performance.memory) {
    console.log({
      used: performance.memory.usedJSHeapSize,
      total: performance.memory.totalJSHeapSize,
      limit: performance.memory.jsHeapSizeLimit
    });
  }
}

// Force garbage collection (dev tools only)
if (window.gc) {
  window.gc();
}
```

questions.backOfCard:
**Explanation:**
• Uses mark-and-sweep algorithm for automatic memory management
• Leaks occur when objects remain unintentionally referenced
• Common causes: closures, event listeners, timers, circular references

**Usage:**
```javascript
// Leak: Forgotten event listener
button.addEventListener('click', handler);
// Solution: Remove listener
button.removeEventListener('click', handler);

// Leak: Uncleaned timer
const id = setInterval(callback, 1000);
// Solution: Clear timer
clearInterval(id);

// Leak: Large closure data
const large = new Array(1000000);
return (i) => large[i]; // Keeps entire array
```

**Real World Example:**
SPA: cleanup event listeners in React useEffect, clear intervals in component unmount, avoid keeping detached DOM references.

