```javascript
// 1. Efficient DOM manipulation
// Bad: Multiple DOM queries and updates
function updateListBad(items) {
  const list = document.getElementById('list');
  list.innerHTML = ''; // Triggers reflow

  items.forEach(item => {
    const li = document.createElement('li');
    li.textContent = item.name;
    list.appendChild(li); // Multiple reflows
  });
}

// Good: Batch DOM operations
function updateListGood(items) {
  const list = document.getElementById('list');
  const fragment = document.createDocumentFragment();

  items.forEach(item => {
    const li = document.createElement('li');
    li.textContent = item.name;
    fragment.appendChild(li); // No reflow until added to DOM
  });

  list.innerHTML = '';
  list.appendChild(fragment); // Single reflow
}

// 2. Object pooling for frequent allocations
class ObjectPool {
  constructor(createFn, resetFn, initialSize = 10) {
    this.createFn = createFn;
    this.resetFn = resetFn;
    this.pool = [];

    for (let i = 0; i < initialSize; i++) {
      this.pool.push(this.createFn());
    }
  }

  get() {
    return this.pool.length > 0 ? this.pool.pop() : this.createFn();
  }

  release(obj) {
    this.resetFn(obj);
    this.pool.push(obj);
  }
}

// Usage for game objects or frequent animations
const particlePool = new ObjectPool(
  () => ({ x: 0, y: 0, vx: 0, vy: 0, life: 0 }),
  (particle) => { particle.x = particle.y = particle.vx = particle.vy = particle.life = 0; }
);

// 3. Efficient array operations
// Bad: Creating new arrays frequently
function filterAndMapBad(items) {
  return items
    .filter(item => item.active)
    .map(item => ({ ...item, processed: true }));
}

// Good: Single pass with reduce
function filterAndMapGood(items) {
  return items.reduce((acc, item) => {
    if (item.active) {
      acc.push({ ...item, processed: true });
    }
    return acc;
  }, []);
}

// 4. Memoization for expensive calculations
function memoize(fn) {
  const cache = new Map();

  return function (...args) {
    const key = JSON.stringify(args);

    if (cache.has(key)) {
      return cache.get(key);
    }

    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

const expensiveCalculation = memoize((n) => {
  console.log('Computing...', n);
  let result = 0;
  for (let i = 0; i < n * 1000000; i++) {
    result += Math.sqrt(i);
  }
  return result;
});

// 5. Web Workers for heavy computations
// main.js
function calculateInWorker(data) {
  return new Promise((resolve, reject) => {
    const worker = new Worker('calculation-worker.js');

    worker.postMessage(data);

    worker.onmessage = (e) => {
      resolve(e.data);
      worker.terminate();
    };

    worker.onerror = (error) => {
      reject(error);
      worker.terminate();
    };
  });
}

// calculation-worker.js
self.onmessage = function(e) {
  const data = e.data;
  // Heavy computation here
  const result = data.map(item => {
    // Complex processing...
    return processItem(item);
  });

  self.postMessage(result);
};

// 6. Lazy loading and code splitting
// Dynamic imports for code splitting
async function loadFeature() {
  const { default: Feature } = await import('./feature-module.js');
  return new Feature();
}

// Intersection Observer for lazy loading
const imageObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      const img = entry.target;
      img.src = img.dataset.src;
      img.classList.remove('lazy');
      imageObserver.unobserve(img);
    }
  });
});

document.querySelectorAll('img[data-src]').forEach(img => {
  imageObserver.observe(img);
});
```

