import React, { ComponentType, forwardRef } from 'react';

// Basic HOC that adds loading functionality
interface WithLoadingProps {
  isLoading: boolean;
}

function withLoading<P extends object>(
  WrappedComponent: ComponentType<P>
) {
  return function WithLoadingComponent(
    props: P & WithLoadingProps
  ) {
    const { isLoading, ...restProps } = props;

    if (isLoading) {
      return <div>Loading...</div>;
    }

    return <WrappedComponent {...restProps as P} />;
  };
}

// Usage
interface UserProfileProps {
  user: User;
  onUpdate: (user: User) => void;
}

const UserProfile: React.FC<UserProfileProps> = ({ user, onUpdate }) => {
  return <div>{user.name}</div>;
};

const UserProfileWithLoading = withLoading(UserProfile);

// Component can be used with both original props and HOC props
<UserProfileWithLoading 
  user={user} 
  onUpdate={handleUpdate} 
  isLoading={loading} 
/>;

// More advanced HOC with optional injected props
interface InjectedAuthProps {
  currentUser: User | null;
  isAuthenticated: boolean;
}

// Props that the HOC will inject
type WithAuthProps = Partial<InjectedAuthProps>;

// HOC that handles authentication
function withAuth<P extends WithAuthProps>(
  WrappedComponent: ComponentType<P>
) {
  return function WithAuthComponent(
    props: Omit<P, keyof InjectedAuthProps> & WithAuthProps
  ) {
    const [currentUser, setCurrentUser] = React.useState<User | null>(null);
    const [isAuthenticated, setIsAuthenticated] = React.useState(false);

    React.useEffect(() => {
      // Authentication logic here
      checkAuthStatus().then(setIsAuthenticated);
      getCurrentUser().then(setCurrentUser);
    }, []);

    const injectedProps: InjectedAuthProps = {
      currentUser,
      isAuthenticated
    };

    return (
      <WrappedComponent 
        {...props as P} 
        {...injectedProps} 
      />
    );
  };
}

// Component that expects auth props
interface DashboardProps extends InjectedAuthProps {
  title: string;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  title, 
  currentUser, 
  isAuthenticated 
}) => {
  if (!isAuthenticated) {
    return <div>Please log in</div>;
  }

  return <div>{title} - Welcome {currentUser?.name}</div>;
};

const DashboardWithAuth = withAuth(Dashboard);

// Only need to pass non-injected props
<DashboardWithAuth title="My Dashboard" />;

// HOC with ref forwarding
function withTheme<P extends object>(
  WrappedComponent: ComponentType<P>
) {
  return forwardRef<any, P & { theme?: string }>(
    function WithThemeComponent(props, ref) {
      const { theme = 'default', ...restProps } = props;

      return (
        <div className={`theme-${theme}`}>
          <WrappedComponent {...restProps as P} ref={ref} />
        </div>
      );
    }
  );
}

// Generic HOC factory with options
interface HOCOptions {
  displayName?: string;
  pure?: boolean;
}

function createHOC<TInjectedProps extends object>(
  injectProps: () => TInjectedProps,
  options: HOCOptions = {}
) {
  return function <P extends Partial<TInjectedProps>>(
    WrappedComponent: ComponentType<P>
  ) {
    const HOC = (props: Omit<P, keyof TInjectedProps>) => {
      const injectedProps = injectProps();

      return (
        <WrappedComponent 
          {...props as P} 
          {...injectedProps} 
        />
      );
    };

    HOC.displayName = options.displayName || 
      `withHOC(${WrappedComponent.displayName || WrappedComponent.name})`;

    return HOC;
  };
}

// Usage of generic HOC factory
const withUserData = createHOC(
  () => ({ userData: getCurrentUserData() }),
  { displayName: 'withUserData' }
);
```

