// Different component variants
interface ButtonProps extends BaseProps {
  variant: 'button';
  onClick: () => void;
  disabled?: boolean;
}

interface LinkProps extends BaseProps {
  variant: 'link';
  href: string;
  target?: string;
}

interface TextProps extends BaseProps {
  variant: 'text';
  as?: 'span' | 'div' | 'p';
}

type ComponentProps = ButtonProps | LinkProps | TextProps;

// Conditional type to get props based on variant
type PropsForVariant<T> = 
  T extends 'button' ? ButtonProps :
  T extends 'link' ? LinkProps :
  T extends 'text' ? TextProps :
  never;

// Generic component with conditional props
function SmartComponent<V extends ComponentProps['variant']>(
  props: PropsForVariant<V>
) {
  switch (props.variant) {
    case 'button':
      const buttonProps = props as ButtonProps;
      return <button onClick={buttonProps.onClick}>Button</button>;
    case 'link':
      const linkProps = props as LinkProps;
      return <a href={linkProps.href}>Link</a>;
    case 'text':
      const textProps = props as TextProps;
      return <span>Text</span>;
  }
}

// Usage with full type safety
<SmartComponent<'button'> 
  variant="button" 
  onClick={() => {}} 
  disabled={true} 
/>

// Error: Property 'href' does not exist on type 'ButtonProps'
// <SmartComponent<'button'> variant="button" href="..." />

// Recursive conditional types for deep object transformation
type DeepReadonly<T> = {
  readonly [P in keyof T]: T[P] extends object ? DeepReadonly<T[P]> : T[P];
};

interface NestedObject {
  user: {
    profile: {
      name: string;
      settings: {
        theme: string;
      };
    };
  };
}

type ReadonlyNested = DeepReadonly<NestedObject>;
// All nested properties are readonly

// Conditional types for form validation
type RequiredFields<T> = {
  [K in keyof T]: T[K] extends undefined ? never : K;
}[keyof T];

type OptionalFields<T> = {
  [K in keyof T]: T[K] extends undefined ? K : never;
}[keyof T];

interface FormData {
  name: string;
  email: string;
  age?: number;
  newsletter?: boolean;
}

type Required = RequiredFields<FormData>; // 'name' | 'email'
type Optional = OptionalFields<FormData>; // 'age' | 'newsletter'
```

