```typescript
// Basic mapped type syntax
type Readonly<T> = {
  readonly [P in keyof T]: T[P];
};

type Partial<T> = {
  [P in keyof T]?: T[P];
};

// API response modeling example
interface User {
  id: number;
  name: string;
  email: string;
  password: string;
  createdAt: Date;
  updatedAt: Date;
}

// Create API-safe version without sensitive fields
type ApiUser = Omit<User, 'password'>;

// Transform all properties to strings for form handling
type UserFormData = {
  [K in keyof User]: string;
};
// Result: { id: string; name: string; email: string; ... }

// Conditional property transformation
type StringifyDates<T> = {
  [K in keyof T]: T[K] extends Date ? string : T[K];
};

type ApiSafeUser = StringifyDates<User>;
// Result: dates become strings, other types unchanged

// Advanced: API response with different loading states
type LoadingStates<T> = {
  [K in keyof T as `${string & K}Loading`]: boolean;
} & {
  [K in keyof T as `${string & K}Error`]: string | null;
} & {
  [K in keyof T]: T[K] | null;
};

interface AppData {
  users: User[];
  posts: Post[];
  comments: Comment[];
}

type AppLoadingState = LoadingStates<AppData>;
// Result: {
//   usersLoading: boolean;
//   usersError: string | null;
//   users: User[] | null;
//   postsLoading: boolean;
//   postsError: string | null;
//   posts: Post[] | null;
//   // ... etc
// }

// Practical API client type generation
interface ApiEndpoints {
  getUser: (id: number) => Promise<User>;
  updateUser: (id: number, data: Partial<User>) => Promise<User>;
  deleteUser: (id: number) => Promise<void>;
  getUsers: () => Promise<User[]>;
}

// Extract parameter types from API methods
type ApiParams<T> = {
  [K in keyof T]: T[K] extends (...args: infer P) => any ? P : never;
};

// Extract return types from API methods
type ApiReturns<T> = {
  [K in keyof T]: T[K] extends (...args: any[]) => infer R ? R : never;
};

type UserApiParams = ApiParams<ApiEndpoints>;
// Result: {
//   getUser: [number];
//   updateUser: [number, Partial<User>];
//   deleteUser: [number];
//   getUsers: [];
// }

// Nullable API responses for error handling
type NullableApiResponse<T> = {
  [K in keyof T]: T[K] extends Promise<infer U> 
    ? Promise<U | null>
    : T[K] extends (...args: any[]) => Promise<infer U>
    ? (...args: Parameters<T[K]>) => Promise<U | null>
    : T[K];
};

// Form validation type generation
interface ValidationRules {
  required?: boolean;
  minLength?: number;
  maxLength?: number;
  pattern?: RegExp;
  custom?: (value: any) => boolean;
}

type FormValidation<T> = {
  [K in keyof T]?: ValidationRules;
};

type UserFormValidation = FormValidation<User>;
// Each field can have optional validation rules

// API cache key generation
type CacheKeys<T> = {
  [K in keyof T as `cache_${string & K}`]: string;
};

type UserCacheKeys = CacheKeys<{
  profile: User;
  preferences: UserPreferences;
  history: UserAction[];
}>;
// Result: {
//   cache_profile: string;
//   cache_preferences: string;
//   cache_history: string;
// }

// Database query builder types
type QueryFields<T> = {
  [K in keyof T]?: {
    eq?: T[K];
    ne?: T[K];
    in?: T[K][];
    notIn?: T[K][];
  } & (T[K] extends string ? {
    like?: string;
    ilike?: string;
  } : {}) & (T[K] extends number ? {
    gt?: number;
    gte?: number;
    lt?: number;
    lte?: number;
  } : {});
};

type UserQuery = QueryFields<User>;
// Generates appropriate query operators based on field types

// Real-world API client implementation
class TypedApiClient<T extends Record<string, (...args: any[]) => Promise<any>>> {
  private baseUrl: string;

  constructor(baseUrl: string) {
    this.baseUrl = baseUrl;
  }

  // Type-safe API call method
  async call<K extends keyof T>(
    endpoint: K,
    ...args: Parameters<T[K]>
  ): Promise<Awaited<ReturnType<T[K]>>> {
    // Implementation here
    const response = await fetch(`${this.baseUrl}/${String(endpoint)}`);
    return response.json();
  }
}

const apiClient = new TypedApiClient<ApiEndpoints>('/api');
// Full type safety for all API calls
const user = await apiClient.call('getUser', 123);
const users = await apiClient.call('getUsers');
```

