// wrappers/chart-library.ts
interface ChartConfig {
  type: 'line' | 'bar' | 'pie';
  data: Array<{ label: string; value: number }>;
  options?: {
    responsive?: boolean;
    legend?: boolean;
    colors?: string[];
  };
}

