export function createChart(config: ChartConfig): Chart {
  const chart = new UntypedChartLibrary.Chart(config);

  return {
    render(container: HTMLElement) {
      chart.renderTo(container);
    },
    update(data: ChartConfig['data']) {
      chart.setData(data);
    },
    destroy() {
