    }
  };
}

// 5. Using type assertions carefully
interface ApiClient {
  get<T>(url: string): Promise<T>;
  post<T>(url: string, data: any): Promise<T>;
}

// Temporary solution while waiting for proper types
const untypedApiClient = require('some-api-client');
const apiClient = untypedApiClient as ApiClient;

// Better: Create a typed adapter
class TypedApiAdapter implements ApiClient {
  private client: any;

  constructor() {
    this.client = require('some-api-client');
  }

  async get<T>(url: string): Promise<T> {
    const response = await this.client.get(url);
    return response.data as T;
  }

  async post<T>(url: string, data: any): Promise<T> {
    const response = await this.client.post(url, data);
    return response.data as T;
