// Example code that benefits from strict configuration
// Without strict mode, these would be potential runtime errors

// 1. Strict null checks prevent null reference errors
interface User {
  id: number;
  name: string;
  email?: string; // Optional property
}

function greetUser(user: User | null) {
  // Error without strictNullChecks: user might be null
  // console.log(`Hello, ${user.name}`);

  // Correct: null check required
  if (user) {
    console.log(`Hello, ${user.name}`);

    // Error: email might be undefined
    // console.log(user.email.toLowerCase());

    // Correct: undefined check required
    if (user.email) {
      console.log(user.email.toLowerCase());
    }
  }
}

// 2. No implicit any prevents loose typing
// Error: Parameter 'data' implicitly has an 'any' type
// function processData(data) {
//   return data.someProperty;
// }

// Correct: explicit typing required
function processData(data: { someProperty: string }) {
  return data.someProperty;
}

// 3. Strict function types prevent unsafe assignments
type Handler = (event: MouseEvent) => void;
type GenericHandler = (event: Event) => void;

// Error in strict mode: MouseEvent is not assignable to Event parameter
// const handler: Handler = (event: Event) => {};

// Correct: proper parameter contravariance
const handler: Handler = (event: MouseEvent) => {
  console.log(event.clientX, event.clientY);
};

// 4. Strict property initialization for classes
class UserService {
  // Error: Property 'apiUrl' has no initializer
  // private apiUrl: string;

  // Correct: initialize in declaration
  private apiUrl: string = '/api';

  // Or initialize in constructor
  private timeout: number;

  constructor(timeout: number = 5000) {
    this.timeout = timeout;
  }

  // Or use definite assignment assertion (use sparingly)
  private config!: Config; // Assert it will be assigned before use

  init(config: Config) {
    this.config = config;
  }
}

// 5. Exact optional property types
interface Options {
  debug?: boolean;
}

function configure(options: Options) {
  // With exactOptionalPropertyTypes, this differentiates:
  // { debug: undefined } vs { } (missing debug property)
  if (options.debug === undefined) {
    // This could mean debug was explicitly set to undefined
    // or the property is missing entirely
  }
}

// 6. Unknown in catch variables
try {
  throw new Error('Something went wrong');
} catch (error) {
  // Error is 'unknown' type, must check before using
  if (error instanceof Error) {
    console.log(error.message);
  } else {
    console.log('Unknown error:', String(error));
  }
}

// 7. No unchecked indexed access
interface UserMap {
  [key: string]: User;
}

function getUser(users: UserMap, id: string) {
  const user = users[id]; // Type is User | undefined

  // Error: user might be undefined
  // console.log(user.name);

  // Correct: check for existence
  if (user) {
    console.log(user.name);
  }

  return user;
}

