```typescript
// Type hierarchy for examples
class Animal {
  name: string;
  constructor(name: string) {
    this.name = name;
  }
}

class Dog extends Animal {
  breed: string;
  constructor(name: string, breed: string) {
    super(name);
    this.breed = breed;
  }
  bark() {
    console.log('Woof!');
  }
}

class Poodle extends Dog {
  size: string;
  constructor(name: string, size: string) {
    super(name, 'Poodle');
    this.size = size;
  }
}

// 1. COVARIANCE - Arrays are covariant in TypeScript
// If Dog extends Animal, then Dog[] should be assignable to Animal[]
const dogs: Dog[] = [new Dog('Buddy', 'Golden Retriever')];
const animals: Animal[] = dogs; // ✓ This works (covariant)

// However, this can lead to runtime errors:
// animals.push(new Animal('Cat')); // Compiles but breaks type safety!

// 2. CONTRAVARIANCE - Function parameters are contravariant
// If Dog extends Animal, then (animal: Animal) => void should be assignable to (dog: Dog) => void

type AnimalHandler = (animal: Animal) => void;
type DogHandler = (dog: Dog) => void;

const handleAnimal: AnimalHandler = (animal: Animal) => {
  console.log(animal.name); // Can only use Animal properties
};

const handleDog: DogHandler = (dog: Dog) => {
  console.log(dog.name);
  dog.bark(); // Can use Dog-specific methods
};

// Contravariance: A function that accepts Animal can handle Dog
const dogHandler: DogHandler = handleAnimal; // ✓ This works
// The opposite would NOT be safe:
// const animalHandler: AnimalHandler = handleDog; // ✗ Error

// 3. Function return types are COVARIANT
// If Dog extends Animal, then () => Dog should be assignable to () => Animal

type AnimalFactory = () => Animal;
type DogFactory = () => Dog;

const createDog: DogFactory = () => new Dog('Rex', 'Labrador');
const createAnimal: AnimalFactory = createDog; // ✓ This works (covariant)

// 4. BIVARIANCE - Method parameters (historical TypeScript behavior)
// TypeScript historically allowed both directions for method parameters

class AnimalShelter {
  addAnimal(animal: Animal) {
    console.log(`Added ${animal.name}`);
  }
}

class DogShelter {
  addAnimal(dog: Dog) {
    console.log(`Added dog ${dog.name} (${dog.breed})`);
  }
}

// With method bivariance (older TS behavior):
// let shelter: AnimalShelter = new DogShelter(); // Would work
// let dogShelter: DogShelter = new AnimalShelter(); // Would also work

// Modern TypeScript with strictFunctionTypes: true uses contravariance

// 5. Practical examples with generic types

// Producer types (covariant)
interface Producer<out T> {
  produce(): T;
}

const dogProducer: Producer<Dog> = {
  produce: () => new Dog('Rover', 'Beagle')
};

const animalProducer: Producer<Animal> = dogProducer; // ✓ Covariant

// Consumer types (contravariant)
interface Consumer<in T> {
  consume(item: T): void;
}

const animalConsumer: Consumer<Animal> = {
  consume: (animal: Animal) => console.log(animal.name)
};

const dogConsumer: Consumer<Dog> = animalConsumer; // ✓ Contravariant

// 6. Mutable types (invariant) - neither covariant nor contravariant
interface MutableBox<T> {
  value: T;
  set(value: T): void;
  get(): T;
}

// This would be unsafe if allowed:
// const dogBox: MutableBox<Dog> = new MutableBox<Dog>();
// const animalBox: MutableBox<Animal> = dogBox; // ✗ Should not work
// animalBox.set(new Animal('Cat')); // Would break type safety!

// 7. Function variance in practice

// Event handlers demonstrate contravariance
type EventHandler<T> = (event: T) => void;

interface SpecificEvent extends Event {
  customData: string;
}

const genericEventHandler: EventHandler<Event> = (event) => {
  console.log('Event occurred');
};

// Can use a more general handler for specific events
const specificEventHandler: EventHandler<SpecificEvent> = genericEventHandler;

// 8. Variance annotations (TypeScript 4.7+)

// Explicit covariance
interface ReadonlyArray<out T> {
  readonly length: number;
  readonly [n: number]: T;
  map<U>(fn: (value: T) => U): ReadonlyArray<U>;
}

// Explicit contravariance
interface Comparator<in T> {
  compare(a: T, b: T): number;
}

// Invariant (default)
interface Array<T> {
  length: number;
  [n: number]: T;
  push(...items: T[]): number;
  pop(): T | undefined;
}

// 9. Variance in conditional types

// Helper type to check variance
type IsCovariant<T, U> = T extends U ? true : false;

// Test covariance
type DogArrayIsAnimalArray = IsCovariant<Dog[], Animal[]>; // true
type AnimalArrayIsDogArray = IsCovariant<Animal[], Dog[]>; // false

// Test function contravariance
type AnimalHandlerIsDogHandler = IsCovariant<
  (animal: Animal) => void,
  (dog: Dog) => void
>; // true (contravariant parameters)

// 10. Real-world implications

// Safe array operations with variance awareness
function safeArrayOperation<T extends U, U>(
  source: readonly T[],
  target: U[]
): void {
  // Can read from source (covariant)
  const item: U = source[0]; // ✓ T extends U, so T is assignable to U

  // Can write to target (contravariant)
  target.push(item);
}

// Usage
const poodles: Poodle[] = [new Poodle('Fluffy', 'small')];
const dogs: Dog[] = [];

safeArrayOperation(poodles, dogs); // ✓ Safe: Poodle[] -> Dog[]
```

