    { id: 2, text: 'Task 2', completed: false }
  ]);

  // GOOD - separate state for different concerns
  const [todoItems, setTodoItems] = useState({});
  const [todoOrder, setTodoOrder] = useState([1, 2]);

  const toggleTodo = useCallback((id) => {
    setTodoItems(prev => ({
      ...prev,
      [id]: { ...prev[id], completed: !prev[id].completed }
    }));
  }, []);
}

// 5. Use proper keys
function TodoList({ todos }) {
  return (
    <ul>
      {todos.map((todo, index) => (
        // BAD - using index as key
        <li key={index}>{todo.text}</li>

        // GOOD - using stable unique identifier
        <li key={todo.id}>{todo.text}</li>
      ))}
    </ul>
  );
}

// 6. Lifting state up vs keeping it local
function Form() {
  // Keep form state local if not needed elsewhere
  const [formData, setFormData] = useState({ name: '', email: '' });

  // Don't lift to parent unless necessary
  return (
    <form>
      <input 
        value={formData.name}
        onChange={e => setFormData(prev => ({ ...prev, name: e.target.value }))}
      />
    </form>
  );
}

// 7. Use React DevTools Profiler
// Wrap components to identify re-render causes
function ProfiledComponent() {
  return (
    <Profiler id="ExpensiveComponent" onRender={onRenderCallback}>
      <ExpensiveComponent />
    </Profiler>
  );
}
```

