const cluster = require('cluster');
const os = require('os');
const redis = require('redis');
const compression = require('compression');
const express = require('express');

// 1. Clustering for Multi-Core Usage
if (cluster.isMaster) {
  const numCPUs = os.cpus().length;
  console.log(`Master process ${process.pid} starting ${numCPUs} workers`);

  // Fork workers
  for (let i = 0; i < numCPUs; i++) {
    cluster.fork();
  }

  cluster.on('exit', (worker, code, signal) => {
    console.log(`Worker ${worker.process.pid} died. Restarting...`);
    cluster.fork();
  });
} else {
  // Worker process
  const app = express();

  // 2. Compression Middleware
  app.use(compression());

  // 3. Redis Caching
  const redisClient = redis.createClient();

  async function getCachedData(key) {
    try {
      const cached = await redisClient.get(key);
      return cached ? JSON.parse(cached) : null;
    } catch (error) {
      console.error('Redis error:', error);
      return null;
    }
  }

  async function setCachedData(key, data, expireSeconds = 3600) {
    try {
      await redisClient.setex(key, expireSeconds, JSON.stringify(data));
    } catch (error) {
      console.error('Redis set error:', error);
    }
  }

  // 4. Optimized Route with Caching
  app.get('/api/products', async (req, res) => {
    const cacheKey = `products:${req.query.category || 'all'}`;

    // Try cache first
    let products = await getCachedData(cacheKey);

    if (!products) {
      // Database query with optimizations
      products = await db.query(`
        SELECT p.id, p.name, p.price, c.name as category_name
        FROM products p
        INNER JOIN categories c ON p.category_id = c.id
        WHERE p.active = 1
        ORDER BY p.created_at DESC
        LIMIT 100
      `);

      // Cache the results
      await setCachedData(cacheKey, products, 1800); // 30 minutes
    }

    res.json(products);
  });

  // 5. Database Connection Pooling
  const mysql = require('mysql2/promise');

  const pool = mysql.createPool({
    host: 'localhost',
    user: 'user',
    password: 'password',
    database: 'ecommerce',
    waitForConnections: true,
    connectionLimit: 10,
    queueLimit: 0,
    acquireTimeout: 60000,
    timeout: 60000
  });

  // 6. Memory Usage Monitoring
  function monitorMemory() {
    const used = process.memoryUsage();
    console.log('Memory Usage:');
    for (let key in used) {
      console.log(`${key}: ${Math.round(used[key] / 1024 / 1024 * 100) / 100} MB`);
    }

    // Alert if heap usage is too high
    if (used.heapUsed > 500 * 1024 * 1024) { // 500MB
      console.warn('High memory usage detected!');
      // Could trigger cleanup or restart
    }
  }

  setInterval(monitorMemory, 30000); // Every 30 seconds

  // 7. Event Loop Lag Monitoring
  function measureEventLoopLag() {
    const start = process.hrtime.bigint();
    setImmediate(() => {
      const lag = Number(process.hrtime.bigint() - start) / 1000000; // Convert to ms
      if (lag > 10) { // More than 10ms lag
        console.warn(`Event loop lag: ${lag.toFixed(2)}ms`);
      }
    });
  }

  setInterval(measureEventLoopLag, 5000);

  // 8. Profiling with Node.js Built-in Profiler
  // Start with: node --prof app.js
  // Analyze with: node --prof-process isolate-*.log

  // 9. Stream Processing for Large Data
  const fs = require('fs');
  const csv = require('csv-parser');

  app.get('/api/export-orders', (req, res) => {
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', 'attachment; filename=orders.csv');

    // Stream data instead of loading all into memory
    const query = db.query('SELECT * FROM orders');
    query.stream()
      .pipe(csv())
      .pipe(res);
  });

  // 10. Async/Await Best Practices
  app.get('/api/user-dashboard/:userId', async (req, res) => {
    try {
      // Run independent queries in parallel
      const [user, orders, wishlist] = await Promise.all([
        db.query('SELECT * FROM users WHERE id = ?', [req.params.userId]),
        db.query('SELECT * FROM orders WHERE user_id = ? LIMIT 10', [req.params.userId]),
        db.query('SELECT * FROM wishlist WHERE user_id = ?', [req.params.userId])
      ]);

      res.json({ user: user[0], orders, wishlist });
    } catch (error) {
      console.error('Dashboard error:', error);
      res.status(500).json({ error: 'Failed to load dashboard' });
    }
  });

  app.listen(3000, () => {
    console.log(`Worker ${process.pid} started on port 3000`);
  });
}

// Performance monitoring tools:
