const mysql = require('mysql2/promise');
const { Pool } = require('pg');
const mongoose = require('mongoose');

// ===== MYSQL CONNECTION POOLING =====

// Create connection pool
const mysqlPool = mysql.createPool({
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 3306,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,

  // Pool configuration
  connectionLimit: 10,              // Maximum connections in pool
  acquireTimeout: 60000,           // Max time to get connection (ms)
  timeout: 60000,                  // Query timeout (ms)
  reconnect: true,                 // Reconnect on connection loss
  queueLimit: 0,                   // No limit on queued requests

  // Connection management
  waitForConnections: true,        // Queue requests when no connections
  removeNodeErrorCount: 5,         // Remove connection after 5 errors
  restoreNodeTimeout: 0,           // Time before reconnecting failed connection

  // SSL configuration for production
  ssl: process.env.NODE_ENV === 'production' ? {
    rejectUnauthorized: false
  } : false
});

// Database service class
class DatabaseService {
  static async query(sql, params = []) {
    const connection = await mysqlPool.getConnection();
    try {
      const [results] = await connection.execute(sql, params);
      return results;
    } catch (error) {
      console.error('Database query error:', error);
      throw error;
    } finally {
      connection.release(); // Return connection to pool
    }
  }

  static async transaction(queries) {
    const connection = await mysqlPool.getConnection();
    try {
      await connection.beginTransaction();

      const results = [];
      for (const { sql, params } of queries) {
        const [result] = await connection.execute(sql, params);
        results.push(result);
      }

      await connection.commit();
      return results;
    } catch (error) {
      await connection.rollback();
      console.error('Transaction error:', error);
      throw error;
    } finally {
      connection.release();
    }
  }

  // Check pool status
  static getPoolInfo() {
    return {
      totalConnections: mysqlPool._allConnections.length,
      activeConnections: mysqlPool._acquiringConnections.length,
      freeConnections: mysqlPool._freeConnections.length,
      queuedRequests: mysqlPool._connectionQueue.length
    };
  }
}

// ===== POSTGRESQL CONNECTION POOLING =====

const pgPool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool settings
  max: 20,                    // Maximum clients in pool
  min: 5,                     // Minimum clients in pool
  idleTimeoutMillis: 30000,   // Close idle clients after 30s
  connectionTimeoutMillis: 2000, // Wait 2s for connection

  // SSL for production
  ssl: process.env.NODE_ENV === 'production' ? {
    rejectUnauthorized: false
  } : false
});

class PostgreSQLService {
  static async query(text, params = []) {
    const client = await pgPool.connect();
    try {
      const result = await client.query(text, params);
      return result.rows;
    } catch (error) {
      console.error('PostgreSQL query error:', error);
      throw error;
    } finally {
      client.release();
    }
  }

  static async transaction(callback) {
    const client = await pgPool.connect();
    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }
}

// ===== MONGODB CONNECTION POOLING (MONGOOSE) =====

// Mongoose handles connection pooling internally
mongoose.connect(process.env.MONGODB_URI, {
  // Connection pool settings
  maxPoolSize: 10,           // Maximum connections
  minPoolSize: 5,            // Minimum connections
  maxIdleTimeMS: 30000,      // Close connections after 30s idle
  serverSelectionTimeoutMS: 5000, // Server selection timeout
  socketTimeoutMS: 45000,    // Socket timeout
  bufferMaxEntries: 0,       // Disable mongoose buffering
  bufferCommands: false,     // Disable mongoose buffering
});

// MongoDB connection events
mongoose.connection.on('connected', () => {
  console.log('MongoDB connected');
});

mongoose.connection.on('error', (err) => {
  console.error('MongoDB connection error:', err);
});

mongoose.connection.on('disconnected', () => {
  console.log('MongoDB disconnected');
});

// ===== CONNECTION HEALTH MONITORING =====

class ConnectionMonitor {
  static async checkMySQLHealth() {
    try {
      await mysqlPool.execute('SELECT 1');
      return { status: 'healthy', timestamp: new Date() };
    } catch (error) {
      return { status: 'unhealthy', error: error.message, timestamp: new Date() };
    }
  }

  static async checkPostgreSQLHealth() {
    try {
      await pgPool.query('SELECT 1');
      return { status: 'healthy', timestamp: new Date() };
    } catch (error) {
      return { status: 'unhealthy', error: error.message, timestamp: new Date() };
    }
  }

  static async checkMongoDBHealth() {
    try {
      const state = mongoose.connection.readyState;
      const states = ['disconnected', 'connected', 'connecting', 'disconnecting'];
      return { 
        status: state === 1 ? 'healthy' : 'unhealthy',
        state: states[state],
        timestamp: new Date()
      };
    } catch (error) {
      return { status: 'unhealthy', error: error.message, timestamp: new Date() };
    }
  }
}

// ===== USAGE EXAMPLES =====

// Express.js route examples
const express = require('express');
const app = express();

// MySQL example - Get user orders
app.get('/api/users/:userId/orders', async (req, res) => {
  try {
    const orders = await DatabaseService.query(
      `SELECT o.*, p.name as product_name, p.price 
       FROM orders o 
       JOIN order_items oi ON o.id = oi.order_id
       JOIN products p ON oi.product_id = p.id
       WHERE o.user_id = ?
       ORDER BY o.created_at DESC`,
      [req.params.userId]
    );
    res.json(orders);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch orders' });
  }
});

// Transaction example - Place order
app.post('/api/orders', async (req, res) => {
  const { userId, items, totalAmount } = req.body;

  try {
    const results = await DatabaseService.transaction([
      {
        sql: 'INSERT INTO orders (user_id, total_amount, status) VALUES (?, ?, ?)',
        params: [userId, totalAmount, 'pending']
      },
      {
        sql: 'UPDATE users SET total_spent = total_spent + ? WHERE id = ?',
        params: [totalAmount, userId]
      }
      // Add order items queries...
    ]);

    res.json({ orderId: results[0].insertId, status: 'success' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to create order' });
  }
});

// Health check endpoint
app.get('/health/database', async (req, res) => {
  const health = await Promise.all([
    ConnectionMonitor.checkMySQLHealth(),
    ConnectionMonitor.checkPostgreSQLHealth(),
    ConnectionMonitor.checkMongoDBHealth()
  ]);

  res.json({
    mysql: health[0],
    postgresql: health[1], 
    mongodb: health[2],
    poolInfo: DatabaseService.getPoolInfo()
  });
});

// Graceful shutdown
process.on('SIGINT', async () => {
  console.log('Closing database connections...');
  await mysqlPool.end();
  await pgPool.end();
  await mongoose.connection.close();
  process.exit(0);
});
```

