const winston = require('winston');
const express = require('express');
const prometheus = require('prom-client');
const rateLimit = require('express-rate-limit');

// ===== STRUCTURED LOGGING WITH WINSTON =====

// Create logger with multiple transports
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.colorize({ all: true }),
    winston.format.printf(({ timestamp, level, message, stack, ...meta }) => {
      let logMessage = `${timestamp} [${level}]: ${message}`;

      // Add stack trace for errors
      if (stack) {
        logMessage += `\n${stack}`;
      }

      // Add metadata
      if (Object.keys(meta).length > 0) {
        logMessage += `\n${JSON.stringify(meta, null, 2)}`;
      }

      return logMessage;
    })
  ),
  transports: [
    // Console for development
    new winston.transports.Console({
      level: 'debug'
    }),

    // File for all logs
    new winston.transports.File({
      filename: 'logs/app.log',
      level: 'info',
      maxsize: 10485760, // 10MB
      maxFiles: 5,
      format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.json()
      )
    }),

    // Separate file for errors
    new winston.transports.File({
      filename: 'logs/error.log',
      level: 'error',
      maxsize: 10485760,
      maxFiles: 5,
      format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.json()
      )
    })
  ],

  // Don't exit on uncaught exceptions
  exitOnError: false
});

// ===== METRICS COLLECTION WITH PROMETHEUS =====

// Create metric collectors
const httpRequestsTotal = new prometheus.Counter({
  name: 'http_requests_total',
  help: 'Total number of HTTP requests',
  labelNames: ['method', 'route', 'status_code']
});

const httpRequestDuration = new prometheus.Histogram({
  name: 'http_request_duration_seconds',
  help: 'HTTP request duration in seconds',
  labelNames: ['method', 'route', 'status_code'],
  buckets: [0.1, 0.3, 0.5, 0.7, 1, 3, 5, 7, 10]
});

const activeConnections = new prometheus.Gauge({
  name: 'active_connections',
  help: 'Number of active database connections'
});

const memoryUsage = new prometheus.Gauge({
  name: 'nodejs_memory_usage_bytes',
  help: 'Node.js memory usage in bytes',
  labelNames: ['type']
});

// Collect default metrics (CPU, memory, etc.)
prometheus.collectDefaultMetrics({ timeout: 5000 });

// ===== EXPRESS APP WITH MONITORING MIDDLEWARE =====

const app = express();

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();

  // Log incoming request
  logger.info('Incoming request', {
    method: req.method,
    url: req.url,
    userAgent: req.get('User-Agent'),
    ip: req.ip,
    requestId: req.get('X-Request-ID') || 'unknown'
  });

  // Override res.end to capture response metrics
  const originalEnd = res.end;
  res.end = function(...args) {
    const duration = (Date.now() - start) / 1000;
    const route = req.route ? req.route.path : req.url;

    // Record metrics
    httpRequestsTotal.inc({
      method: req.method,
      route: route,
      status_code: res.statusCode
    });

    httpRequestDuration.observe(
      {
        method: req.method,
        route: route,
        status_code: res.statusCode
      },
      duration
    );

    // Log response
    logger.info('Request completed', {
      method: req.method,
      url: req.url,
      statusCode: res.statusCode,
      duration: `${duration}s`,
      requestId: req.get('X-Request-ID') || 'unknown'
    });

    originalEnd.apply(this, args);
  };

  next();
});

// ===== HEALTH CHECK ENDPOINTS =====

const healthChecks = {
  async database() {
    try {
      // Check database connection
      await db.query('SELECT 1');
      return { status: 'healthy', responseTime: '< 100ms' };
    } catch (error) {
      return { status: 'unhealthy', error: error.message };
    }
  },

  async redis() {
    try {
      const start = Date.now();
      await redisClient.ping();
      const responseTime = Date.now() - start;
      return { status: 'healthy', responseTime: `${responseTime}ms` };
    } catch (error) {
      return { status: 'unhealthy', error: error.message };
    }
  },

  async externalAPI() {
    try {
      const response = await fetch('https://api.example.com/health', {
        timeout: 5000
      });
      return {
        status: response.ok ? 'healthy' : 'unhealthy',
        statusCode: response.status
      };
    } catch (error) {
      return { status: 'unhealthy', error: error.message };
    }
  },

  memory() {
    const usage = process.memoryUsage();
    const totalMB = Math.round(usage.heapTotal / 1024 / 1024);
    const usedMB = Math.round(usage.heapUsed / 1024 / 1024);
    const usage_percent = Math.round((usage.heapUsed / usage.heapTotal) * 100);

    return {
      status: usage_percent < 90 ? 'healthy' : 'warning',
      heapUsed: `${usedMB}MB`,
      heapTotal: `${totalMB}MB`,
      usage_percent: `${usage_percent}%`
    };
  }
};

// Basic health check
app.get('/health', (req, res) => {
  res.json({
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    version: process.env.npm_package_version
  });
});

// Detailed health check
app.get('/health/detailed', async (req, res) => {
  try {
    const checks = await Promise.allSettled([
      healthChecks.database(),
      healthChecks.redis(),
      healthChecks.externalAPI()
    ]);

    const results = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      checks: {
        database: checks[0].status === 'fulfilled' ? checks[0].value : { status: 'error', error: checks[0].reason },
        redis: checks[1].status === 'fulfilled' ? checks[1].value : { status: 'error', error: checks[1].reason },
        externalAPI: checks[2].status === 'fulfilled' ? checks[2].value : { status: 'error', error: checks[2].reason },
        memory: healthChecks.memory()
      }
    };

    // Determine overall status
    const hasUnhealthy = Object.values(results.checks).some(
      check => check.status === 'unhealthy' || check.status === 'error'
    );

    if (hasUnhealthy) {
      results.status = 'degraded';
      res.status(503);
    }

    res.json(results);
  } catch (error) {
    logger.error('Health check failed', error);
    res.status(503).json({
      status: 'unhealthy',
      error: 'Health check failed'
    });
  }
});

// Metrics endpoint for Prometheus
app.get('/metrics', async (req, res) => {
  try {
    // Update memory metrics before serving
    const memUsage = process.memoryUsage();
    memoryUsage.set({ type: 'rss' }, memUsage.rss);
    memoryUsage.set({ type: 'heapTotal' }, memUsage.heapTotal);
    memoryUsage.set({ type: 'heapUsed' }, memUsage.heapUsed);

    res.set('Content-Type', prometheus.register.contentType);
    res.end(await prometheus.register.metrics());
  } catch (error) {
    res.status(500).end(error);
  }
});

// ===== ERROR HANDLING AND MONITORING =====

// Global error handler
app.use((error, req, res, next) => {
  const errorId = `error_${Date.now()}_${Math.random().toString(36)}`;

  logger.error('Unhandled application error', {
    errorId,
    message: error.message,
    stack: error.stack,
    url: req.url,
    method: req.method,
    userAgent: req.get('User-Agent'),
    ip: req.ip
  });

  res.status(500).json({
    error: 'Internal server error',
    errorId,
    timestamp: new Date().toISOString()
  });
});

// Process-level error handling
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection', {
    reason,
    promise: promise.toString()
  });
});

// ===== PERFORMANCE MONITORING =====

// Monitor event loop lag
const eventLoopMonitor = setInterval(() => {
  const start = process.hrtime.bigint();
  setImmediate(() => {
    const lag = Number(process.hrtime.bigint() - start) / 1000000;
    if (lag > 100) { // More than 100ms
      logger.warn('High event loop lag detected', { lag: `${lag}ms` });
    }
  });
}, 5000);

// Memory monitoring
const memoryMonitor = setInterval(() => {
  const usage = process.memoryUsage();
  const usagePercent = (usage.heapUsed / usage.heapTotal) * 100;

  if (usagePercent > 85) {
    logger.warn('High memory usage detected', {
      heapUsed: Math.round(usage.heapUsed / 1024 / 1024),
      heapTotal: Math.round(usage.heapTotal / 1024 / 1024),
      usagePercent: Math.round(usagePercent)
    });
  }
}, 30000);

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  clearInterval(eventLoopMonitor);
  clearInterval(memoryMonitor);
  server.close(() => {
    logger.info('Process terminated');
    process.exit(0);
  });
});

const server = app.listen(3000, () => {
  logger.info('Server started', { port: 3000 });
});
