```javascript
const cluster = require('cluster');
const os = require('os');
const express = require('express');
const redis = require('redis');
const session = require('express-session');
const RedisStore = require('connect-redis')(session);

// ===== HORIZONTAL SCALING - CLUSTERING =====

if (cluster.isMaster) {
  const numCPUs = os.cpus().length;
  const numWorkers = process.env.NUM_WORKERS || numCPUs;

  console.log(`Master process ${process.pid} starting ${numWorkers} workers`);

  // Fork workers
  for (let i = 0; i < numWorkers; i++) {
    const worker = cluster.fork();

    // Track worker performance
    worker.on('message', (msg) => {
      if (msg.type === 'performance') {
        console.log(`Worker ${worker.process.pid} performance:`, msg.data);
      }
    });
  }

  // Handle worker crashes
  cluster.on('exit', (worker, code, signal) => {
    console.log(`Worker ${worker.process.pid} died (${code || signal}). Restarting...`);
    const newWorker = cluster.fork();
    console.log(`New worker ${newWorker.process.pid} started`);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('Master received SIGTERM, shutting down workers...');

    Object.values(cluster.workers).forEach(worker => {
      worker.kill('SIGTERM');
    });

    setTimeout(() => {
      console.log('Force killing remaining workers');
      Object.values(cluster.workers).forEach(worker => {
        worker.kill('SIGKILL');
      });
    }, 10000);
  });

} else {
  // Worker process
  const app = express();
  const redisClient = redis.createClient({
    host: process.env.REDIS_HOST || 'localhost',
    port: process.env.REDIS_PORT || 6379
  });

  // ===== STATELESS APPLICATION DESIGN =====

  // Use Redis for session storage (shared across workers)
  app.use(session({
    store: new RedisStore({ client: redisClient }),
    secret: process.env.SESSION_SECRET,
    resave: false,
    saveUninitialized: false,
    cookie: {
      secure: process.env.NODE_ENV === 'production',
      maxAge: 24 * 60 * 60 * 1000 // 24 hours
    }
  }));

  // ===== CACHING LAYER =====

  class CacheService {
    static async get(key) {
      try {
        const value = await redisClient.get(key);
        return value ? JSON.parse(value) : null;
      } catch (error) {
        console.error('Cache get error:', error);
        return null;
      }
    }

    static async set(key, value, ttlSeconds = 3600) {
      try {
        await redisClient.setex(key, ttlSeconds, JSON.stringify(value));
      } catch (error) {
        console.error('Cache set error:', error);
      }
    }

    static async invalidate(pattern) {
      try {
        const keys = await redisClient.keys(pattern);
        if (keys.length > 0) {
          await redisClient.del(keys);
        }
      } catch (error) {
        console.error('Cache invalidation error:', error);
      }
    }
  }

  // ===== DATABASE CONNECTION OPTIMIZATION =====

  const mysql = require('mysql2/promise');

  // Read replica for scaling reads
  const readPool = mysql.createPool({
    host: process.env.DB_READ_HOST,
    user: process.env.DB_USER,
    password: process.env.DB_PASSWORD,
    database: process.env.DB_NAME,
    connectionLimit: 10,
    acquireTimeout: 60000
  });

  // Write master for scaling writes
  const writePool = mysql.createPool({
    host: process.env.DB_WRITE_HOST,
    user: process.env.DB_USER,
    password: process.env.DB_PASSWORD,
    database: process.env.DB_NAME,
    connectionLimit: 5,
    acquireTimeout: 60000
  });

  class DatabaseService {
    static async read(query, params = []) {
      return await readPool.execute(query, params);
    }

    static async write(query, params = []) {
      return await writePool.execute(query, params);
    }
  }

  // ===== OPTIMIZED API ENDPOINTS =====

  // Product catalog with caching
  app.get('/api/products', async (req, res) => {
    const { category, page = 1, limit = 20 } = req.query;
    const cacheKey = `products:${category || 'all'}:${page}:${limit}`;

    try {
      // Try cache first
      let products = await CacheService.get(cacheKey);

      if (!products) {
        // Query from read replica
        const offset = (page - 1) * limit;
        const [rows] = await DatabaseService.read(
          `SELECT p.id, p.name, p.price, p.image_url, c.name as category
           FROM products p
           JOIN categories c ON p.category_id = c.id
           WHERE p.active = 1 ${category ? 'AND c.slug = ?' : ''}
           ORDER BY p.featured DESC, p.created_at DESC
           LIMIT ? OFFSET ?`,
          category ? [category, parseInt(limit), offset] : [parseInt(limit), offset]
        );

        products = rows;

        // Cache for 30 minutes
        await CacheService.set(cacheKey, products, 1800);
      }

      res.json({
        products,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          hasMore: products.length === parseInt(limit)
        }
      });

    } catch (error) {
      console.error('Error fetching products:', error);
      res.status(500).json({ error: 'Failed to fetch products' });
    }
  });

  // Order creation with write optimization
  app.post('/api/orders', async (req, res) => {
    const { userId, items, shippingAddress } = req.body;

    try {
      // Calculate total (could be cached if complex)
      const totalAmount = items.reduce((sum, item) => {
        return sum + (item.price * item.quantity);
      }, 0);

      // Write to master database
      const [result] = await DatabaseService.write(
        'INSERT INTO orders (user_id, total_amount, shipping_address, status) VALUES (?, ?, ?, ?)',
        [userId, totalAmount, JSON.stringify(shippingAddress), 'pending']
      );

      const orderId = result.insertId;

      // Invalidate user's order cache
      await CacheService.invalidate(`user:${userId}:orders*`);

      // Queue background tasks (inventory update, email, etc.)
      await queueBackgroundJob('process-order', { orderId, userId, items });

      res.status(201).json({
        orderId,
        status: 'created',
        totalAmount
      });

    } catch (error) {
      console.error('Error creating order:', error);
      res.status(500).json({ error: 'Failed to create order' });
    }
  });

  // ===== BACKGROUND JOB PROCESSING =====

  const Queue = require('bull');
  const processOrderQueue = new Queue('process order', {
    redis: {
      host: process.env.REDIS_HOST,
      port: process.env.REDIS_PORT
    }
  });

  async function queueBackgroundJob(type, data) {
    try {
      await processOrderQueue.add(type, data, {
        attempts: 3,
        backoff: 'exponential',
        delay: 1000
      });
    } catch (error) {
      console.error('Failed to queue job:', error);
    }
  }

  // Process jobs (only in one worker to avoid duplication)
  if (cluster.worker.id === 1) {
    processOrderQueue.process('process-order', async (job) => {
      const { orderId, userId, items } = job.data;

      // Update inventory
      for (const item of items) {
        await DatabaseService.write(
          'UPDATE products SET stock = stock - ? WHERE id = ?',
          [item.quantity, item.productId]
        );
      }

      // Send confirmation email (async)
      // await sendOrderConfirmationEmail(userId, orderId);

      console.log(`Processed order ${orderId}`);
    });
  }

  // ===== PERFORMANCE MONITORING =====

  let requestCount = 0;
  let responseTimeTotal = 0;

  app.use((req, res, next) => {
    const start = process.hrtime.bigint();

    res.on('finish', () => {
      const duration = Number(process.hrtime.bigint() - start) / 1000000;
      requestCount++;
      responseTimeTotal += duration;

      // Send performance data to master every 1000 requests
      if (requestCount % 1000 === 0) {
        process.send({
          type: 'performance',
          data: {
            workerId: cluster.worker.id,
            pid: process.pid,
            requestCount,
            avgResponseTime: responseTimeTotal / requestCount,
            memoryUsage: process.memoryUsage()
          }
        });
      }
    });

    next();
  });

  // ===== HEALTH CHECK FOR LOAD BALANCER =====

  app.get('/health', (req, res) => {
    const memUsage = process.memoryUsage();
    const uptime = process.uptime();

    // Health check criteria
    const isHealthy = (
      memUsage.heapUsed < 500 * 1024 * 1024 && // Less than 500MB
      uptime > 10 // Running for more than 10 seconds
    );

    res.status(isHealthy ? 200 : 503).json({
      status: isHealthy ? 'healthy' : 'unhealthy',
      worker: cluster.worker.id,
      pid: process.pid,
      uptime,
      memory: {
        heapUsed: Math.round(memUsage.heapUsed / 1024 / 1024),
        heapTotal: Math.round(memUsage.heapTotal / 1024 / 1024)
      }
    });
  });

  // Graceful shutdown for worker
  const server = app.listen(process.env.PORT || 3000, () => {
    console.log(`Worker ${cluster.worker.id} (PID: ${process.pid}) listening on port ${process.env.PORT || 3000}`);
  });

  process.on('SIGTERM', () => {
    console.log(`Worker ${process.pid} received SIGTERM, shutting down gracefully`);

    server.close(() => {
      redisClient.quit();
      readPool.end();
      writePool.end();
      process.exit(0);
    });
  });
}

// ===== DOCKER CONFIGURATION FOR SCALING =====

// Dockerfile
/*
FROM node:18-alpine
WORKDIR /app
COPY package*.json ./
RUN npm ci --only=production
COPY . .
EXPOSE 3000
CMD ["node", "app.js"]
*/

// docker-compose.yml for local scaling
/*
version: '3.8'
services:
  app:
    build: .
    environment:
      - NODE_ENV=production
      - NUM_WORKERS=2
      - REDIS_HOST=redis
      - DB_HOST=mysql
    depends_on:
      - redis
      - mysql
    deploy:
      replicas: 3

  nginx:
    image: nginx:alpine
    ports:
      - "80:80"
    volumes:
      - ./nginx.conf:/etc/nginx/nginx.conf
    depends_on:
      - app

  redis:
    image: redis:alpine

  mysql:
    image: mysql:8.0
    environment:
      MYSQL_ROOT_PASSWORD: password
*/
```

